// One immutable monochrome noise tile. No animation or regeneration on scroll.
const tile=document.createElement('canvas');tile.width=tile.height=256;
const context=tile.getContext('2d'), pixels=context.createImageData(256,256);let seed=271828;
for(let i=0;i<pixels.data.length;i+=4){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const value=seed>>>24;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=value;pixels.data[i+3]=255;}
context.putImageData(pixels,0,0);const grain=document.getElementById('grain');grain.style.backgroundImage=`url(${tile.toDataURL()})`;
const strength=document.getElementById('strength'),toggle=document.getElementById('toggle');let enabled=true;
function updateGrain(){grain.style.opacity=enabled?Number(strength.value)/100:0;document.getElementById('amount').value=`${strength.value}%`;toggle.setAttribute('aria-pressed',String(enabled));toggle.textContent=enabled?'Grain on':'Grain off';}
strength.oninput=()=>{enabled=true;updateGrain();};toggle.onclick=()=>{enabled=!enabled;updateGrain();};updateGrain();
const words=[['serendipity','noun','The occurrence of happy discoveries by chance.'],['serendipitous','adjective','Occurring or discovered by chance in a happy way.'],['serene','adjective','Peaceful, calm, and untroubled.'],['serenity','noun','The state of being calm and peaceful.'],['serried','adjective','Standing close together in rows.'],['serum','noun','The clear fluid separated from clotted blood.']];
const search=document.getElementById('search'),results=document.getElementById('results');
function renderSearch(){results.replaceChildren();const query=search.value.trim().toLowerCase();const matches=query?words.filter(w=>w[0].includes(query)):[];for(const w of matches){const entry=document.createElement('div');entry.className='entry';const title=document.createElement('div');title.append(document.createTextNode(w[0]));const tag=document.createElement('small');tag.textContent=w[1];title.append(tag);const gloss=document.createElement('p');gloss.textContent=w[2];entry.append(title,gloss);results.append(entry);}if(!matches.length){const empty=document.createElement('p');empty.className='empty';empty.textContent=query?'No matches in this sample.':'Look up a word to get started.';results.append(empty);}}
search.oninput=renderSearch;document.getElementById('clear').onclick=()=>{search.value='';renderSearch();search.focus();};renderSearch();
let index=0,revealed=false;const card=document.getElementById('card');function renderCard(){document.getElementById('word').textContent=words[index][0];document.getElementById('pos').textContent=words[index][1];document.getElementById('definition').textContent=words[index][2];document.getElementById('definition').hidden=true;document.getElementById('grades').hidden=true;document.getElementById('hint').hidden=false;document.getElementById('count').textContent=`${index+1} / 6`;document.getElementById('progress').style.width=`${(index+1)/6*100}%`;revealed=false;}
card.onclick=()=>{revealed=true;document.getElementById('definition').hidden=false;document.getElementById('grades').hidden=false;document.getElementById('hint').hidden=true;};document.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{if(!revealed)return;index=(index+1)%words.length;renderCard();document.getElementById('feedback').textContent=`${b.dataset.grade} · Next sample word`;card.focus();});document.getElementById('start').onclick=()=>{index=0;renderCard();document.getElementById('session-status').textContent='Sample session ready →';document.getElementById('session').scrollIntoView({behavior:'auto',block:'center'});card.focus({preventScroll:true});};renderCard();
